  // Dispose old window
  var oldWin = this.window;
  this.window = undefined;
  this.document = undefined;
  try { if (oldWin.happyDOM && typeof oldWin.happyDOM.close === 'function') oldWin.happyDOM.close(); } catch(e) {}
  // Load fresh (this creates a new App with empty todos from fresh localStorage)
  this.loadApp();
  // Restore localStorage into new window and re-render
  if (storedData) {
    this.window.localStorage.setItem('todos-vanillajs', storedData);
    if (this.window.app) {
      this.window.app.todos = JSON.parse(storedData);
      this.window.app.render();
